// => Many mountains are behind clouds today.

// Regex.Replace with a MatchEvaluator
string source = "The mountains are still there behind the clouds today.";

// \s keeps "there" from matching
string result = Regex.Replace(
    source,
    """the\s""",
    match => char.IsUpper(match.Value[0]) ? "Many " : "many ",
    RegexOptions.IgnoreCase);

Console.WriteLine(result);
// => Many mountains are still there behind many clouds today.

// Edit characters through Span<char>
string phrase = "The quick brown fox jumps over the fence.";

// Strings are immutable, so edit a Span<char> copy
Span<char> characters = stackalloc char[phrase.Length];
phrase.CopyTo(characters);
int index = phrase.IndexOf("fox");
if (index != -1)
{
    characters[index] = 'c';
    characters[index + 1] = 'a';
    characters[index + 2] = 't';
}

string updated = new string(characters);
Console.WriteLine(updated);
// => The quick brown cat jumps over the fence.

string root = @"C:\users";
string root2 = @"C:\Users";

// Case-sensitive ordinal comparison
Console.WriteLine(root.Equals(root2));
// => False
Console.WriteLine(root == root2);
// => False
Console.WriteLine(root.Equals(root2, StringComparison.Ordinal));
// => False

// Ordinal case-insensitive comparison
string root = @"C:\users";
