    {
        static void Main()
        {
            Person p1 = new("Alex", 9);
            Console.WriteLine($"p1 Name = {p1.Name} Age = {p1.Age}");

            // Copies the struct
            Person p2 = p1;
            p2.Name = "Spencer";
            p2.Age = 7;
            Console.WriteLine($"p2 Name = {p2.Name} Age = {p2.Age}");

            // p1 is unchanged
            Console.WriteLine($"p1 Name = {p1.Name} Age = {p1.Age}");
        }
    }
}

