// Implicitly inherits from Object
public class WorkItem
{
    private static int currentID;

    protected int ID { get; set; }
    protected string Title { get; set; }
    protected string Description { get; set; }
    protected TimeSpan jobLength { get; set; }

    // Called implicitly if a derived class doesn't call a base constructor
    public WorkItem()
    {
        ID = 0;
        Title = "Default title";
        Description = "Default description.";
        jobLength = new TimeSpan();
    }
    public WorkItem(string title, string desc, TimeSpan joblen)
    {
        this.ID = GetNextID();
        this.Title = title;
        this.Description = desc;
        this.jobLength = joblen;
    }

    // Runs once, before first use
    static WorkItem() => currentID = 0;

    protected int GetNextID() => ++currentID;

    public void Update(string title, TimeSpan joblen)
    {
        this.Title = title;
        this.jobLength = joblen;
    }

    public override string ToString() =>
        $"{this.ID} - {this.Title}";
}

public class ChangeRequest : WorkItem
{
    protected int originalItemID { get; set; }

    // Neither constructor calls a base constructor, so the base needs a parameterless one

    public ChangeRequest() { }

    public ChangeRequest(string title, string desc, TimeSpan jobLen,
                         int originalID)
    {
        // Inherited from WorkItem
        this.ID = GetNextID();
        this.Title = title;
        this.Description = desc;
        this.jobLength = jobLen;

        this.originalItemID = originalID;
    }
}

WorkItem item = new WorkItem("Fix Bugs",
                            "Fix all bugs in my code branch",
                            new TimeSpan(3, 4, 0, 0));

ChangeRequest change = new ChangeRequest("Change Base Class Design",
                                        "Add members to the class",
                                        new TimeSpan(4, 0, 0),
                                        1);

Console.WriteLine(item.ToString());

// Inherited method
change.Update("Change the Design of the Base Class",
    new TimeSpan(4, 0, 0));

// Inherits WorkItem's ToString override
Console.WriteLine(change.ToString());

