// Extension block (C# 14)
public static class Enumerable
{
    extension<TSource>(IEnumerable<TSource> source) // extension members for IEnumerable<TSource>
    {
        public bool IsEmpty => !source.Any();

        public IEnumerable<TSource> Where(Func<TSource, bool> predicate) { ... }
    }

    // Receiver type only: static extensions
    extension<TSource>(IEnumerable<TSource>) // static extension members for IEnumerable<Source>
    {
        public static IEnumerable<TSource> Combine(IEnumerable<TSource> first,
IEnumerable<TSource> second) { ... }

        public static IEnumerable<TSource> Identity => Enumerable.Empty<TSource>();

        public static IEnumerable<TSource> operator + (IEnumerable<TSource> left,
IEnumerable<TSource> right) => left.Concat(right);
    }
}

private string _msg;
public string Message
{
    get => _msg;
    set => _msg = value ?? throw new ArgumentNullException(nameof(value));
}

// field keyword (C# 14)
public string Message
{
    get;
    set => field = value ?? throw new ArgumentNullException(nameof(value));
}

// Lazy init with field ??=
public SqlConnection Connection
{
    get => field ??= new SqlConnection("connection-string");
}
public string DisplayName
{
    get;
    set
    {
        if (field == value) return;
        field = value;
        OnPropertyChanged();
    }
}
public string Email
{
    get;
    set => field = value?.Trim()?.ToLowerInvariant() ?? string.Empty;
}

