public void SetHighGate(bool open)
{
    HighWaterGateOpen = open;
}

public void SetLowGate(bool open)
{
    LowWaterGateOpen = open;
}

public void SetWaterLevel(WaterLevel newLevel)
{
    CanalLockWaterLevel = newLevel;
}

