// Covariant type parameter (out)
interface ICovariant<out R>
{
    R GetSomething();
    // void SetSomething(R sampleArg); // Error: out type as a parameter
}

// Covariant parameter in a contravariant delegate
interface ICovariant<out R>
{
    void DoSomething(Action<R> callback);
}

// Not allowed as a method constraint
interface ICovariant<out R>
{
    // void DoSomething<T>() where T : R; // Error: covariant type in a constraint
}

// Contravariant type parameter (in)
interface IContravariant<in A>
{
    void SetSomething(A sampleArg);
    void DoSomething<T>() where T : A;
    // A GetSomething(); // Error: in type as a return value
}

// Both in and out
interface IVariant<out R, in A>
{
    R GetSomething();
    void SetSomething(A sampleArg);
    R GetSetSomethings(A sampleArg);
}

interface ICovariant<out R>
{
    R GetSomething();
}
