// Static constructor runs once
public class Bus
{
    protected static readonly DateTime globalStartTime;

    protected int RouteNumber { get; set; }

    static Bus()
    {
        globalStartTime = DateTime.Now;

        // Printed only once
        Console.WriteLine($"Static constructor sets global start time to {globalStartTime.ToLongTimeString()}");
    }

    public Bus(int routeNum)
    {
        RouteNumber = routeNum;
        Console.WriteLine($"Bus #{RouteNumber} is created.");
    }

    public void Drive()
    {
        TimeSpan elapsedTime = DateTime.Now - globalStartTime;

        Console.WriteLine($"{this.RouteNumber} is starting its route {elapsedTime.Milliseconds:N2} minutes after global start time
{globalStartTime.ToShortTimeString()}.");
    }
}

