// Callers can forget to check IsSuccess
public sealed class QueryResult<T>
{
    private QueryResult(bool isSuccess, T? value, Exception? error)
    {
        IsSuccess = isSuccess;
        Value = value;
        Error = error;
    }

    public bool IsSuccess { get; }
    public T? Value { get; }
    public Exception? Error { get; }

    public static QueryResult<T> Success(T value) => new(true, value, null);
    public static QueryResult<T> Failure(Exception error) => new(false, default,
error);
}

public union Result<T>(T, Exception);

