// with(...) arguments (C# 15)
public static void CollectionExpressionWithArgumentsExample()
{
    string[] values = ["one", "two", "three"];

    List<string> names = [with(capacity: values.Length * 2), .. values];

    Console.WriteLine($"Created List<string> with capacity: {names.Capacity}");
    Console.WriteLine($"List contains {names.Count} elements: [{string.Join(", ",
names)}]");

    HashSet<string> caseInsensitiveSet = [with(StringComparer.OrdinalIgnoreCase),
"Hello", "HELLO"];
    // One element: the comparer ignores case

    Console.WriteLine($"HashSet with case-insensitive comparer contains {caseInsensitiveSet.Count} elements: [{string.Join(", ", caseInsensitiveSet)}]");
    Console.WriteLine("Note: 'Hello' and 'HELLO' are treated as the same element
due to OrdinalIgnoreCase comparer");
}

